arguments.command:
cat > /tmp/binlog-reader/Program.cs << 'CSHARP'
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Collect all errors
var errors = new List<(string project, string code, string message, string file, int line)>();
build.VisitAllChildren<Error>(e => {
    var proj = "";
    var node = e.Parent;
    while (node != null) {
        if (node is Project p) { proj = p.Name; break; }
        if (node is Target t && t.Project is Project tp) { proj = tp.Name; break; }
        node = node.Parent as BaseNode;
    }
    errors.Add((proj, e.Code ?? "", e.ToString(), e.File ?? "", e.LineNumber));
});

// Collect all warnings
var warnings = new List<(string project, string code, string message)>();
build.VisitAllChildren<Warning>(w => {
    var proj = "";
    var node = w.Parent;
    while (node != null) {
        if (node is Project p) { proj = p.Name; break; }
        if (node is Target t && t.Project is Project tp) { proj = tp.Name; break; }
        node = node.Parent as BaseNode;
    }
    warnings.Add((proj, w.Code ?? "", w.ToString()));
});

Console.WriteLine("=== BUILD ERRORS ===");
foreach (var g in errors.GroupBy(e => e.project)) {
    Console.WriteLine($"\n--- Project: {g.Key} ---");
    foreach (var e in g) {
        Console.WriteLine($"  [{e.code}] {e.file}({e.line}): {e.message}");
    }
}

Console.WriteLine("\n=== BUILD WARNINGS (may be relevant) ===");
foreach (var g in warnings.GroupBy(w => w.project)) {
    Console.WriteLine($"\n--- Project: {g.Key} ---");
    foreach (var w in g) {
        Console.WriteLine($"  [{w.code}] {w.message}");
    }
}

// Show project dependency info
Console.WriteLine("\n=== PROJECT BUILD RESULTS ===");
build.VisitAllChildren<Project>(p => {
    if (p.Name.EndsWith(".csproj") || p.Name.EndsWith(".fsproj") || p.Name.EndsWith(".vbproj")) {
        Console.WriteLine($"  {p.Name} -> Succeeded={p.Succeeded}");
    }
});
