cat > /tmp/binlog-reader/Program.cs << 'CSHARP'
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Show all projects and their structure
Console.WriteLine("=== ALL PROJECTS ===");
build.VisitAllChildren<Project>(p => {
    Console.WriteLine($"  {p.Name} | ProjectFile={p.ProjectFile}");
});

// Show project references (look for items)
Console.WriteLine("\n=== PROJECT REFERENCES & PACKAGE REFERENCES ===");
build.VisitAllChildren<Project>(p => {
    if (!p.Name.EndsWith(".csproj")) return;
    Console.WriteLine($"\n--- {p.Name} ---");
    p.VisitAllChildren<Item>(item => {
        if (item.Name == "ProjectReference" || item.Name == "PackageReference") {
            Console.WriteLine($"  {item.Name}: {item.Text}");
        }
    });
});

// Show file contents from the binlog if embedded
Console.WriteLine("\n=== SOURCE FILES REFERENCED ===");
build.VisitAllChildren<Error>(e => {
    Console.WriteLine($"  File: {e.File} Line: {e.LineNumber}");
});
