cat > /tmp/binlog-reader/Program.cs << 'CSHARP'
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Get detailed package/project references with metadata
Console.WriteLine("=== PACKAGE REFERENCES WITH DETAILS ===");
build.VisitAllChildren<AddItem>(item => {
    if (item.Name == "PackageReference" || item.Name == "ProjectReference") {
        var proj = "";
        TreeNode node = item.Parent;
        while (node != null) {
            if (node is Project p) { proj = p.Name; break; }
            node = node.Parent as TreeNode;
        }
        Console.WriteLine($"  {proj} -> {item.Name}: ");
        foreach (var child in item.Children) {
            Console.WriteLine($"    {child}");
        }
    }
});

// Also look at the embedded files / source content
Console.WriteLine("\n=== LOOKING FOR EMBEDDED SOURCE FILES ===");
var sourceFiles = build.SourceFiles;
if (sourceFiles != null) {
    foreach (var kvp in sourceFiles) {
        Console.WriteLine($"  File: {kvp.Key} ({kvp.Value.Length} chars)");
    }
}
